    block = unique_unit_data[coord]
    r, c = coord
    for br in range(10):
        for bc in range(10):
            result[r*10+br][c*10+bc] = block[br][bc]

print(f"Result shape: {len(result)} x {len(result[0])}")
print("Result corner:", result[0][0])

# Try local transformation: within each 10x10 block, apply some sorting
# Or keep blocks same but transform how they're displayed

def sort_block_by_row(grid_block, sortAsc=True):
    """Sort each row within a block"""
    return [sorted(row, reverse=not sortAsc) for row in grid_block]

# Apply row-sorting to each block and reassemble
sorted_blocks = {}
for coord, block in unique_unit_data.items():
    sorted_blocks[coord] = sort_block_by_row(block)

